main.script:
document.addEventListener("DOMContentLoaded", () => {
    const root = document.getElementById("sunapp_saas_progress");
    const title = document.getElementById("sunapp_saas_title");
    const message = document.getElementById("sunapp_saas_message");
    const spinner = document.getElementById("sunapp_saas_spinner");
    let attempts = 0;

    async function refreshStatus() {
        attempts += 1;
        try {
            const response = await fetch(root.dataset.statusUrl, {
                cache: "no-store",
                headers: {"Accept": "application/json"},
            });
            const result = await response.json();
            if (result.status === "ready") {
                spinner.classList.add("d-none");
                title.textContent = "Votre espace SunApp est prêt";
                message.textContent = "Vos accès vous seront transmis par e-mail.";
                return;
            }
        } catch (error) {
            // A temporary network error must not interrupt status polling.
        }
        if (attempts === 100) {
            message.textContent = "La préparation prend un peu plus de temps. Vous recevrez vos accès par e-mail dès qu'elle sera terminée.";
        }
        window.setTimeout(refreshStatus, 5000);
    }

    window.setTimeout(refreshStatus, 2000);
});
